package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.physics.*;

/**
 * Diagnostic showing the orbit epoch mismatch problem
 *
 * Generated by Claude (Sonnet 4.5)
 */
public class EpochMismatchDiagnostic {

    public static void diagnoseManeuverChain(ManeuverDetails first) {
        System.out.println("=== ORBIT EPOCH DIAGNOSTIC ===\n");

        ManeuverDetails current = first;
        int index = 0;

        while (current != null) {
            System.out.printf("Maneuver %d: %s\n", index, current.getId());
            System.out.printf("  Start time: %.1f\n", current.getStartTime());
            System.out.printf("  End time:   %.1f\n", current.getEndTime());

            if (current.getOrbit() != null) {
                System.out.printf("  Orbit epoch: %.1f\n",
                        current.getOrbit().epoch());

                double epochDelta = current.getOrbit().epoch() -
                        current.getStartTime();

                if (Math.abs(epochDelta) > 1.0) {
                    System.out.printf("  ERROR: Epoch mismatch! Delta = %.1f seconds\n",
                            epochDelta);
                    System.out.println("  This will cause position errors in telemetry!");
                } else {
                    System.out.println("  OK: Epoch matches maneuver start");
                }
            }

            System.out.println();
            current = current.getNext();
            index++;
        }
    }

    public static void demonstrateProblem() {
        System.out.println("=== DEMONSTRATING THE EPOCH PROBLEM ===\n");

        System.out.println("SCENARIO:");
        System.out.println("1. Create maneuver at system time T=1000");
        System.out.println("2. Orbit.calculateOrbit() sets epoch to T=1000");
        System.out.println("3. Pass orbit to ManeuverDetails with startTime=5000");
        System.out.println("4. Generate telemetry at timeSinceManeuverStart=100\n");

        System.out.println("WHAT HAPPENS:");
        System.out.println("- calculateOrbitAfterT0(100) propagates from epoch=1000");
        System.out.println("- Calculates position at time 1000+100=1100");
        System.out.println("- But maneuver started at 5000!");
        System.out.println("- We wanted position at 5000+100=5100");
        System.out.println("- Result: 4000 seconds of orbit error\n");

        System.out.println("THE FIX:");
        System.out.println("- Always set orbit.epoch = maneuver.startTime");
        System.out.println("- Then calculateOrbitAfterT0(100) propagates from startTime");
        System.out.println("- Correctly calculates position at startTime+100");
    }

    public static void main(String[] args) {
        demonstrateProblem();
    }
}